<?php
namespace App\Controllers;
use App\Core\Controller;
use App\Models\Setting;
use App\Services\AuditService;
final class SettingsController extends Controller {
 public function index():void{$zones=\App\Core\Database::connection()->query("SELECT * FROM delivery_zones ORDER BY name")->fetchAll();$this->view('settings/index',['settings'=>(new Setting())->allSettings(),'zones'=>$zones,'title'=>'Paramètres KIN-MART']);}
 public function save():void{$m=new Setting();$groups=['company_name'=>'company','company_subtitle'=>'company','company_address'=>'company','company_phone'=>'company','company_whatsapp'=>'company','company_email'=>'company','company_rccm'=>'company','company_idnat'=>'company','company_tax_no'=>'company','company_hours'=>'company','usd_cdf_rate'=>'finance','tax_rate'=>'finance','loyalty_points_per_usd'=>'loyalty','loyalty_points_per_reward'=>'loyalty','loyalty_reward_usd'=>'loyalty','low_stock_days_threshold'=>'analytics','dormant_days'=>'analytics'];foreach($groups as $k=>$g)if(isset($_POST[$k]))$m->set($k,trim((string)$_POST[$k]),$g);if(!empty($_FILES['company_logo']['tmp_name'])){$f=$_FILES['company_logo'];if($f['size']>2*1024*1024)throw new \RuntimeException('Logo trop volumineux (2 Mo max).');$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new \RuntimeException('Format de logo non autorisé.');$name='company-logo-'.date('YmdHis').'.'.$ext;$dest=dirname(__DIR__,2).'/public/uploads/documents/'.$name;if(!move_uploaded_file($f['tmp_name'],$dest))throw new \RuntimeException('Upload logo impossible.');$m->set('company_logo','public/uploads/documents/'.$name,'company');}AuditService::log('UPDATE','SETTINGS',null,$_POST);flash('success','Paramètres enregistrés.');redirect('settings');}

 public function addZone():void{$name=trim($_POST['name']??'');$fee=(float)($_POST['fee_usd']??0);if($name===''){flash('error','Nom de zone obligatoire.');redirect('settings');}$db=\App\Core\Database::connection();$db->prepare("INSERT INTO delivery_zones(name,fee_usd,status) VALUES(?,?,'ACTIVE')")->execute([$name,$fee]);AuditService::log('CREATE','DELIVERY_ZONE',null,['name'=>$name,'fee'=>$fee]);flash('success','Zone de livraison ajoutée.');redirect('settings');}
 public function updateZone(string $id):void{$db=\App\Core\Database::connection();$db->prepare("UPDATE delivery_zones SET fee_usd=?,status=? WHERE id=?")->execute([(float)($_POST['fee_usd']??0),$_POST['status']??'ACTIVE',(int)$id]);flash('success','Zone mise à jour.');redirect('settings');}
}
